import { describe, expect, it } from 'vitest'
import fs from 'node:fs'
import path from 'node:path'
import { ENABLED_LOCALES } from '@/lib/i18n/locales'

// A language appears in the dropdown only when it is finished. "Finished"
// means every string in lib/i18n/catalog.json (regenerated by
// scripts/i18n/extract.mjs) has a translation — a half-translated screen
// reads as broken, which is worse than English.
describe('enabled languages are complete', () => {
  const dir = path.resolve(__dirname, '../../lib/i18n')
  const catalog = JSON.parse(fs.readFileSync(path.join(dir, 'catalog.json'), 'utf8')) as Record<string, string[]>
  const keys = Object.keys(catalog)

  for (const locale of ENABLED_LOCALES.filter((l) => l !== 'en')) {
    it(`${locale} translates every catalog string`, () => {
      const dict = JSON.parse(fs.readFileSync(path.join(dir, 'dictionaries', `${locale}.json`), 'utf8')) as Record<string, string>
      const missing = keys.filter((k) => !dict[k] || !dict[k].trim())
      expect(missing.slice(0, 20), `${missing.length} untranslated in ${locale}`).toEqual([])
    })
  }

  it('the catalog is not empty', () => {
    expect(keys.length).toBeGreaterThan(1000)
  })
})
